export interface UseIteratorPixelOptions<T> {
    /** Number of items to fetch per page */
    limit?: number;
    /** Callback when data is successfully loaded */
    onSuccess?: (data: T[], isLoadingMore: boolean) => void;
    /** Callback when an error occurs */
    onError?: (error: Error) => void;
}
export interface UseIteratorPixelReturn<T> {
    /** Current accumulated data */
    data: T[];
    /** Total count of the data */
    totalCount: number;
    /** Track if errored */
    isError: boolean;
    /** Error if status is ERROR */
    error: Error | null;
    /** Whether currently loading */
    isLoading: boolean;
    /** Whether there are more items to load */
    hasMore: boolean;
    /** Load the next set of items */
    next: () => void;
    /** Reset the state */
    reset: () => void;
}
/**
 * Hook for handling paginated/iterator pixel queries with automatic accumulation
 *
 * @param pixelQuery - Function that generates the pixel query with limit and offset
 * @param getTotalCount - Function to extract total count from response
 * @param getData - Function to extract data array from response
 * @param dependencies - Dependencies that trigger a reset when changed
 * @param options - Configuration options
 *
 * @example
 * ```tsx
 * const { data, hasMore, next, isLoading } = useIteratorPixel(
 *   (limit, offset) => `GetWorkspaceRooms(workspaceId=["${id}"], limit=[${limit}], offset=[${offset}]);`,
 *   (response) => response.total_count,
 *   (response) => response.rooms,
 *   { limit: 25 },
 *   [id]
 * );
 * ```
 */
export declare function useIteratorPixel<TResponse, TItem>(pixelQuery: (limit: number, offset: number) => string, getTotalCount: (response: TResponse) => number, getData: (response: TResponse) => TItem[], options?: UseIteratorPixelOptions<TItem>, dependencies?: React.DependencyList): UseIteratorPixelReturn<TItem>;
